#!/bin/bash
# Builds and runs the host unit tests for the pure game modules (src/game).
set -e
cd "$(dirname "$0")"
mkdir -p build
${CC:-gcc} -std=c99 -W -Wall -Wextra -Werror -o build/tests \
	test_main.c test_trail.c test_cycle.c test_press_latch.c test_arena.c test_trail_pieces.c test_floor_fade.c test_view_cull.c test_wall_clip.c test_turn_ease.c test_depth_fog.c test_turn_gate.c test_collision.c test_minimap.c test_rider.c test_bot.c test_trail_occlusion.c test_game_state.c test_camera_shake.c test_status_message.c test_attract_route.c test_loop_break.c test_intro_flight.c test_arrival_flight.c test_surround.c test_rounds.c test_wall_flicker.c test_breach.c test_corridor.c test_walker.c test_city.c test_frustum.c test_vdp1_gauge.c test_occluder.c test_skyline.c test_lift.c test_landmarks.c test_city_seen.c test_board.c test_target.c test_body.c test_settings.c test_drone.c test_bench.c test_draw_budget.c test_floor_hides.c ../src/game/trail.c ../src/game/cycle.c ../src/game/press_latch.c ../src/game/arena.c ../src/game/trail_pieces.c ../src/game/floor_fade.c ../src/game/view_cull.c ../src/game/wall_clip.c ../src/game/turn_ease.c ../src/game/depth_fog.c ../src/game/turn_gate.c ../src/game/collision.c ../src/game/minimap.c ../src/game/rider.c ../src/game/bot.c ../src/game/trail_occlusion.c ../src/game/game_state.c ../src/game/camera_shake.c ../src/game/status_message.c ../src/game/attract_route.c ../src/game/attract_text.c ../src/game/loop_break.c ../src/game/intro_flight.c ../src/game/arrival_flight.c ../src/game/surround.c ../src/game/rounds.c ../src/game/wall_flicker.c ../src/game/breach.c ../src/game/corridor.c ../src/game/walker.c ../src/game/city.c ../src/game/frustum.c ../src/game/vdp1_gauge.c ../src/game/occluder.c ../src/game/skyline.c ../src/game/lift.c ../src/game/landmarks.c ../src/game/city_seen.c ../src/game/board.c ../src/game/target.c ../src/game/body.c ../src/game/settings.c ../src/game/drone.c ../src/game/bench.c ../src/game/draw_budget.c ../src/game/floor_hides.c
./build/tests
# The film checker's own tests (tests/e2e/glitch.py, SG-6): Python's standard library only
python3 e2e/test_glitch.py
